export async function search(q: string) {
  try {
    return await vectorSearch(q);
  } catch {
    return bruteForceSearch(q);
  }
}

// Jitter avoids synchronised retries after a shared outage.
export function backoff(attempt: number): number {
  return 200 * 2 ** attempt + Math.random() * 100;
}

export interface Store {
  get(key: string): Promise<string | null>;
  set(key: string, value: string): Promise<void>;
}

export class MemoryStore implements Store {
  private m = new Map<string, string>();
  async get(k: string) { return this.m.get(k) ?? null; }
  async set(k: string, v: string) { this.m.set(k, v); }
}

export class RedisStore implements Store {
  constructor(private client: RedisClient) {}
  async get(k: string) { return this.client.get(k); }
  async set(k: string, v: string) { await this.client.set(k, v); }
}
